`timescale 1ns/1ps
// ============================================================================
// spi_slave.v
// SPI slave, redesigned for ASIC-flow friendliness:
//   - Single clock domain: everything is clocked on `clk`. SCLK (an input
//     generated by the master in the same clock domain) is edge-detected
//     synchronously rather than used as a second clock, so there is no
//     generated-clock SDC constraint to write and no CDC to reason about.
//   - No tri-state: `miso` is a dedicated per-slave output. The top-level
//     module muxes the active slave's `miso` onto the shared MISO net,
//     avoiding tristate-buffer synthesis/DRC issues in standard-cell flows.
// ============================================================================
module spi_slave #(
    parameter DATA_WIDTH = 8,
    parameter CPOL       = 0,
    parameter CPHA       = 0
)(
    input  wire                  clk,
    input  wire                  rst_n,

    input  wire                  SCLK,
    input  wire                  SS,     // active low
    input  wire                  MOSI,

    input  wire [DATA_WIDTH-1:0] tx_data,
    output reg  [DATA_WIDTH-1:0] rx_data,
    output reg                   done,
    output reg                   miso    // dedicated line, muxed at top level
);

    // ---- Synchronous SCLK edge detector ----
    reg sclk_d1, sclk_d2;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_d1 <= CPOL;
            sclk_d2 <= CPOL;
        end else begin
            sclk_d1 <= SCLK;
            sclk_d2 <= sclk_d1;
        end
    end

    wire sclk_rising  =  sclk_d1 & ~sclk_d2;
    wire sclk_falling = ~sclk_d1 &  sclk_d2;

    // Mode 0 (CPOL=0, CPHA=0): sample on rising edge, shift on falling edge.
    // General form below supports all 4 SPI modes.
    wire sample_edge = (CPOL ^ CPHA) ? sclk_falling : sclk_rising;
    wire shift_edge  = (CPOL ^ CPHA) ? sclk_rising  : sclk_falling;

    localparam IDLE     = 2'd0,
               TRANSFER = 2'd1,
               DONE_ST  = 2'd2;

    reg [1:0]                      state;
    reg [$clog2(DATA_WIDTH)-1:0]   bit_cnt;
    reg [DATA_WIDTH-1:0]           rx_reg;
    reg [DATA_WIDTH-1:0]           tx_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= IDLE;
            bit_cnt <= 0;
            rx_reg  <= {DATA_WIDTH{1'b0}};
            tx_reg  <= {DATA_WIDTH{1'b0}};
            rx_data <= {DATA_WIDTH{1'b0}};
            miso    <= 1'b0;
            done    <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (!SS) begin
                        tx_reg  <= tx_data;
                        miso    <= tx_data[DATA_WIDTH-1];
                        bit_cnt <= 0;
                        state   <= TRANSFER;
                    end
                end

                TRANSFER: begin
                    // Priority matters here: in CPHA=1 modes the master
                    // deasserts SS the cycle immediately after its own
                    // (zero-latency) detection of the final sample edge,
                    // while this slave detects the same physical SCLK edge
                    // ~2 clk cycles late through the synchronizer above. The
                    // two can land in the same clk cycle, so a live
                    // sample/shift edge must always be serviced before an
                    // SS deassertion is allowed to abort the transfer —
                    // otherwise the last bit of every CPHA=1 transfer is
                    // silently dropped.
                    if (sample_edge) begin
                        rx_reg <= {rx_reg[DATA_WIDTH-2:0], MOSI};
                        if (bit_cnt == $clog2(DATA_WIDTH)'(DATA_WIDTH - 1)) begin
                            rx_data <= {rx_reg[DATA_WIDTH-2:0], MOSI};
                            done    <= 1'b1;
                            state   <= DONE_ST;
                        end else begin
                            bit_cnt <= bit_cnt + 1'b1;
                        end
                    end else if (shift_edge) begin
                        if (bit_cnt == 0) begin
                            // CPHA=1 only: present the already-loaded MSB
                            // without shifting yet (see spi_master.v for
                            // why bit_cnt==0 here only happens in that mode).
                            miso <= tx_reg[DATA_WIDTH-1];
                        end else begin
                            tx_reg <= {tx_reg[DATA_WIDTH-2:0], 1'b0};
                            miso   <= tx_reg[DATA_WIDTH-2];
                        end
                    end else if (SS) begin
                        // No data-phase edge pending this cycle and we've
                        // been deselected — abort safely.
                        state <= IDLE;
                    end
                end

                DONE_ST: begin
                    if (SS) begin
                        done  <= 1'b0;
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule
